(() => {
  const people = [
    ['lin','林妈妈','86 张照片','warm'],['chen','陈叔叔','64 张照片','sage'],['xiaoyu','小雨','52 张照片','rose'],['grandma','外婆','43 张照片','blue'],['momo','沫沫','38 张照片','gold'],['uncle','林叔叔','31 张照片','lav'],['xiaoran','小然','28 张照片','coral'],['dada','达达','22 张照片','mint'],['aunt','周阿姨','19 张照片','peach'],['grandpa','外公','17 张照片','slate'],['qiqi','琪琪','13 张照片','lilac'],['mimi','米米','9 张照片','sand']
  ].map(([id,name,photos,color])=>({id,name,photos,color}));
  const collections = [
    {id:'family',name:'一家人的日常',people:['lin','chen','xiaoyu','grandma'],desc:'那些一起吃饭、散步和庆祝的时刻',count:'4 位人物 · 126 张照片',colors:['warm','sage','rose']},
    {id:'little-days',name:'小朋友们',people:['xiaoyu','momo','xiaoran','qiqi'],desc:'从第一次见面，到长高一点点',count:'4 位人物 · 72 张照片',colors:['rose','gold','coral']},
    {id:'elders',name:'长辈相册',people:['grandma','grandpa','aunt'],desc:'回家的路上，总有熟悉的笑脸',count:'3 位人物 · 51 张照片',colors:['blue','slate','peach']},
    {id:'weekends',name:'周末常见面',people:['lin','momo','dada'],desc:'不用约很久，也能碰面的朋友',count:'3 位人物 · 106 张照片',colors:['mint','lav','sage']},
    {id:'trip',name:'春日出游',people:['chen','xiaoran','qiqi','mimi'],desc:'山风、野餐，还有一张合照',count:'4 位人物 · 92 张照片',colors:['gold','coral','lilac']}
  ];
  const unnamed = [
    {id:'u1',faces:4,photos:3,color:'sand',when:'最近出现 · 2 天前'}, {id:'u2',faces:5,photos:4,color:'blue',when:'最近出现 · 4 天前'},
    {id:'u3',faces:3,photos:2,color:'rose',when:'最近出现 · 1 周前'}, {id:'u4',faces:7,photos:5,color:'sage',when:'最近出现 · 2 周前'},
    {id:'u5',faces:2,photos:2,color:'lav',when:'最近出现 · 3 周前'}, {id:'u6',faces:6,photos:4,color:'gold',when:'最近出现 · 1 个月前'},
    ...Array.from({length:12},(_,i)=>({id:`u${i+7}`,faces:2+(i%7),photos:2+(i%4),color:['mint','peach','slate','lilac','sand','blue'][i%6],when:`最近出现 · ${i+2} 个月前`}))
  ];
  const kinds=['suggested','none','low'];
  const faceData = Array.from({length:36},(_,i)=>({id:`f${i+1}`,kind:kinds[Math.floor(i/12)],color:['warm','sage','rose','blue','gold','lav','coral','mint','peach','slate','lilac','sand'][i%12],label:`照片 · ${String(2025-(i%4))}年${String((i%12)+1).padStart(2,'0')}月`,suggestion:i<12?people[(i*3)%people.length].name:null,confidence:i<12?`${91-(i%7)}%`:null}));
  const ignored = [{id:'h1',state:'TEMPORARY',color:'warm'},{id:'h2',state:'EXCLUDED',color:'rose'},{id:'h3',state:'TEMPORARY',color:'sage'},{id:'h4',state:'EXCLUDED',color:'blue'},{id:'h5',state:'TEMPORARY',color:'gold'},{id:'h6',state:'TEMPORARY',color:'lav'}];
  const initialData={people:JSON.parse(JSON.stringify(people)),collections:JSON.parse(JSON.stringify(collections)),ignored:JSON.parse(JSON.stringify(ignored))};
  const state={selected:new Set(),named:{},confirmed:new Set(),hidden:new Set(),ignoreFilter:'all',toastTimer:0};
  const main=document.querySelector('#main'), modal=document.querySelector('#modal'), toastEl=document.querySelector('#toast');
  const palette={warm:['#d6b29a','#805845','#303a35','#e9d6bd'],sage:['#9cb7a1','#425f50','#2c332f','#d7e2d3'],rose:['#dbaea9','#784b4b','#363533','#efd9d2'],blue:['#98b6c6','#425768','#30383a','#dce8ec'],gold:['#d5b77b','#746043','#373832','#eee4c8'],lav:['#b4aacd','#574c6e','#34313b','#e5dfef'],coral:['#d49a82','#704b40','#333633','#efd7c9'],mint:['#9ebdae','#476253','#303833','#d7e8df'],peach:['#dcb79e','#805f4d','#393734','#f0dfd0'],slate:['#9eabb1','#4e6067','#33383a','#dfe5e5'],lilac:['#c5afd0','#64516d','#35323a','#eee1ef'],sand:['#d4c2a1','#746349','#36342f','#eae1ce']};
  const iconSearch='<svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.7" cy="8.7" r="5.7"/><path d="m13 13 4 4"/></svg>';
  function portrait(color='sage',n=0){const p=palette[color]||palette.sage;const hair=['#3c3530','#544138','#6f5141','#393d3b'][n%4];return `<div class="portrait"><svg viewBox="0 0 100 100" role="img" aria-label="合成插画头像"><defs><linearGradient id="bg${color}${n}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${p[3]}"/><stop offset="1" stop-color="${p[0]}"/></linearGradient></defs><rect width="100" height="100" fill="url(#bg${color}${n})"/><circle cx="18" cy="20" r="17" fill="#fff" opacity=".18"/><path d="M7 100c3-21 17-32 43-32s40 11 43 32" fill="${p[1]}"/><path d="M23 45c0-20 10-31 27-31s28 12 28 32v8H23z" fill="${hair}"/><ellipse cx="50" cy="48" rx="23" ry="27" fill="${p[0]}"/><path d="M26 42c4-17 14-25 27-25 11 0 21 7 25 19-9-4-16-10-20-16-6 11-17 17-32 20z" fill="${hair}"/><path d="M40 49h1m18 0h1" stroke="#493e38" stroke-width="3" stroke-linecap="round"/><path d="M45 61q5 4 10 0" fill="none" stroke="#9e6860" stroke-width="1.8" stroke-linecap="round"/><path d="M33 75q17 12 34 0" fill="none" stroke="#ffffff" stroke-opacity=".32" stroke-width="2"/></svg></div>`;}
  function photoArt(i){const colors=[['#dbe7dc','#6c9683','#f0c889'],['#d9e6ed','#6793a4','#eec4a7'],['#eee0cb','#bf9770','#9eaf91'],['#e6deea','#927b9c','#e8ba9e']][i%4];return `<svg viewBox="0 0 180 120" aria-hidden="true"><rect width="180" height="120" fill="${colors[0]}"/><circle cx="139" cy="26" r="15" fill="#fff" opacity=".7"/><path d="M0 74 43 31l33 35 25-26 79 54v26H0z" fill="${colors[1]}"/><path d="m0 91 46-30 31 25 31-21 72 40v15H0z" fill="${colors[2]}"/><path d="M0 106q45-20 90 0t90 0v14H0z" fill="#f9f7ef" opacity=".55"/><circle cx="67" cy="73" r="8" fill="#f0c6a3"/><path d="M55 103q2-22 12-22t13 22" fill="#a86858"/><circle cx="99" cy="70" r="7" fill="#d9a98e"/><path d="M88 103q1-22 11-22t12 22" fill="#607b66"/></svg>`;}
  function toast(message){toastEl.textContent=message;toastEl.hidden=false;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>toastEl.hidden=true,2600);}
  function route(){let raw=location.hash.slice(1)||'people';const [path,query='']=raw.split('?');const params=new URLSearchParams(query);const parts=path.split('/');return {page:parts[0],id:parts[1],params};}
  function go(path,push=true){state.selected.clear();if(push)location.hash=path;else history.replaceState(null,'',`#${path}`);render();window.scrollTo({top:0,behavior:'smooth'});}
  function tabs(active){const organize=state.organizeRoute||'organize';return `<nav class="tabbar" aria-label="人物页面"><a class="${active==='people'?'active':''}" href="#people" ${active==='people'?'aria-current="page"':''}>人物</a><a class="${active==='collections'?'active':''}" href="#collections" ${active==='collections'?'aria-current="page"':''}>合集</a><a class="${active==='organize'?'active':''}" href="#${esc(organize)}" ${active==='organize'?'aria-current="page"':''}>待整理</a></nav>`;}
  function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><p class="kicker">${kicker}</p><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
  function peoplePage(r){const sort=r.params.get('sort')||'photos';const sorted=[...people].sort((a,b)=>{if(sort==='name')return a.name.localeCompare(b.name,'zh');return parseInt(b.photos)-parseInt(a.photos)});const q=r.params.get('q')||'';const shown=sorted.filter(p=>p.name.includes(q));return `${pageHead('PEOPLE DIRECTORY','认识的人','把熟悉的面孔收在一起，之后找照片更轻松。',`<button id="resetBtn" class="quiet">重置样板</button>`)}${tabs('people')}<div class="layout-row"><label class="searchbox">${iconSearch}<input id="peopleSearch" type="search" placeholder="搜索人物" value="${esc(q)}" aria-label="搜索人物"></label><div class="toolbar"><span class="result-line">${shown.length} 位人物</span><select id="sortSelect" aria-label="人物排序"><option value="photos" ${sort==='photos'?'selected':''}>按照片数量</option><option value="name" ${sort==='name'?'selected':''}>按名字排序</option></select></div></div>${shown.length?`<section class="person-grid">${shown.map(personCard).join('')}</section>`:emptyState('没有找到这个人物','试试其他名字，或清空搜索条件。')}</div>`;}
  function personCard(p){return `<button class="person-card" data-person="${p.id}" aria-label="打开${p.name}">${portrait(p.color,people.indexOf(p))}<strong>${p.name}</strong><small>${p.photos}</small><div class="tiny-meta"><span>已命名</span></div></button>`;}
  function organizePage(r){return unnamedPage(r);}
  function secondaryNav(active){return `<nav class="organize-categories" aria-label="待整理分类"><a href="#${esc(state.unnamedRoute||'unnamed')}" class="${active==='unnamed'?'active':''}" ${active==='unnamed'?'aria-current="page"':''}>未命名人物 <span>${unnamed.filter(g=>!state.hidden.has(g.id)).length} 组</span></a><a href="#${esc(state.facesRoute||'faces')}" class="${active==='faces'?'active':''}" ${active==='faces'?'aria-current="page"':''}>未识别人脸 <span>${faceData.filter(f=>!state.confirmed.has(f.id)).length} 张</span></a></nav>`;}
  function organizeHeader(active){return `${pageHead('PEOPLE','待整理','',`<button id="resetBtn" class="quiet">重置样板</button>`)}${tabs('organize')}<div class="organize-strip">${secondaryNav(active)}<details class="organize-more"><summary>更多操作</summary><div class="organize-menu">${active==='faces'?'<button data-action="updates">识别更新待确认 · 2 条</button><button data-action="tools">识别工具</button>':''}<button data-action="history">操作历史</button></div></details></div><p class="scope-hint">${active==='unnamed'?'已分组但还没有名字的人物。':'还没有确定人物归属的人脸。'}</p>`;}
  function unnamedPage(r){const q=r.params.get('q')||'',page=Math.max(1,Number(r.params.get('page')||1)),sort=r.params.get('sort')||'recent';let filtered=unnamed.filter(g=>!state.hidden.has(g.id)&&(!q||g.id.includes(q)||`未命名人物 ${unnamed.indexOf(g)+1}`.includes(q)));if(sort==='faces')filtered=[...filtered].sort((a,b)=>b.faces-a.faces);const pages=Math.max(1,Math.ceil(filtered.length/6)),actualPage=Math.min(page,pages),start=(actualPage-1)*6,rows=filtered.slice(start,start+6);return `${organizeHeader('unnamed')}<div class="layout-row"><label class="searchbox">${iconSearch}<input id="unnamedSearch" type="search" placeholder="筛选人物组" value="${esc(q)}" aria-label="筛选未命名人物"></label><div class="toolbar"><span class="result-line">${filtered.length?`${start+1}–${Math.min(start+6,filtered.length)} / ${filtered.length} 组`:'0 组'}</span><select id="unnamedSort" aria-label="人物组排序"><option value="recent" ${sort==='recent'?'selected':''}>最近出现</option><option value="faces" ${sort==='faces'?'selected':''}>脸数较多</option></select></div></div>${rows.length?`<section class="group-grid">${rows.map(groupCard).join('')}</section>${pages>1?groupPagination(actualPage,pages,q,sort):''}`:emptyState(q?'没有符合条件的人物组':'暂时没有待命名人物','修改筛选条件，或重置样板数据。')}`;}
  function groupPagination(page,pages,q,sort){let out=`<nav class="pagination" aria-label="未命名人物分页"><button data-group-page="${page-1}" data-q="${esc(q)}" data-sort="${sort}" ${page===1?'disabled':''}>上一页</button>`;for(let i=1;i<=pages;i++)out+=`<button class="${i===page?'current':''}" data-group-page="${i}" data-q="${esc(q)}" data-sort="${sort}" aria-current="${i===page?'page':'false'}">${i}</button>`;return out+`<button data-group-page="${page+1}" data-q="${esc(q)}" data-sort="${sort}" ${page===pages?'disabled':''}>下一页</button><span class="page-label">第 ${page} / ${pages} 页</span></nav>`;}
  function groupCard(g){const ix=unnamed.indexOf(g);return `<article class="group-card"><div class="group-top"><div class="face-stack">${[0,1,2].slice(0,Math.min(3,g.faces)).map((n)=>portrait(g.color,ix+n)).join('')}</div><div class="group-info"><strong>未命名人物 ${String(ix+1).padStart(2,'0')}</strong><small>${g.when}</small></div><span class="group-count">${g.faces} 张脸</span></div><div class="group-foot"><small>${g.photos} 张照片 · 合成头像</small><div class="group-buttons"><button class="primary" data-name-group="${g.id}">取个名字</button><button data-merge-group="${g.id}">并入已有</button></div></div></article>`;}
  function facePage(r){const kind=r.params.get('filter')||'all',page=Math.max(1,Number(r.params.get('page')||1)),q=r.params.get('q')||'';state.faceQuery=q;const filtered=faceData.filter(f=>(kind==='all'||f.kind===kind)&&!state.confirmed.has(f.id)&&(!q||f.id.includes(q)||f.label.includes(q)));const pages=Math.ceil(filtered.length/12)||1;const actualPage=Math.min(page,pages);const start=(actualPage-1)*12;const rows=filtered.slice(start,start+12);const names={all:'全部',suggested:'有建议',none:'暂无建议',low:'低清晰度'};return `${organizeHeader('faces')}<div class="layout-row"><label class="searchbox">${iconSearch}<input id="faceSearch" type="search" placeholder="筛选照片编号" value="${esc(q)}" aria-label="筛选未识别人脸"></label><div class="toolbar"><span class="result-line">${filtered.length?`${start+1}–${Math.min(start+12,filtered.length)} / ${filtered.length} 张`: '0 张'}</span><button class="quiet ignored-entry" data-action="ignored">查看已忽略人脸</button></div></div><div class="toolbar face-filter" role="group" aria-label="人脸类型筛选">${Object.entries(names).map(([key,label])=>`<button class="pill ${key===kind?'active':''}" data-filter="${key}" aria-pressed="${key===kind}">${label}<span class="tab-count">${faceData.filter(f=>(key==='all'||f.kind===key)&&!state.confirmed.has(f.id)).length}</span></button>`).join('')}</div>${state.selected.size?`<div class="selection-bar"><strong>已选 ${state.selected.size} 张人脸</strong><button data-action="clear-selection">取消选择</button><button class="primary" data-action="confirm-selected">确认所选</button></div>`:''}${rows.length?`<section class="faces-grid">${rows.map(faceTile).join('')}</section>${pages>1?pagination(actualPage,pages,kind,q):''}`:emptyState(q?'没有符合条件的人脸':'这里暂时没有人脸','尝试其他筛选条件，或清除搜索内容。')}`;}
  function faceTile(f){const chosen=state.selected.has(f.id),cls=f.kind==='low'?'low':'';let badge=f.kind==='suggested'?`建议 · ${f.suggestion}`:f.kind==='low'?'清晰度较低':'暂无建议';return `<article class="face-tile ${chosen?'selected':''}"><button class="face-check ${chosen?'checked':''}" data-select-face="${f.id}" aria-label="${chosen?'取消':'选择'}${f.id}" aria-pressed="${chosen}">${chosen?'<svg viewBox="0 0 16 16"><path d="m3 8 3 3 7-7"/></svg>':''}</button><span class="face-badge ${cls}">${badge}</span>${portrait(f.color,Number(f.id.slice(1)))}<strong>${f.label}</strong><small>${f.id.toUpperCase()} · ${f.kind==='suggested'?`匹配度 ${f.confidence}`:'等待确认'}</small><div class="face-actions"><button class="quiet" data-confirm-face="${f.id}">${f.kind==='suggested'?'确认人物':'指派人物'}</button></div></article>`;}
  function pagination(page,pages,kind,q){let out=`<nav class="pagination" aria-label="人脸分页"><button data-page="${page-1}" data-filter="${kind}" data-q="${esc(q)}" ${page===1?'disabled':''}>上一页</button>`;for(let i=1;i<=pages;i++)out+=`<button class="${i===page?'current':''}" data-page="${i}" data-filter="${kind}" data-q="${esc(q)}" aria-current="${i===page?'page':'false'}">${i}</button>`;return out+`<button data-page="${page+1}" data-filter="${kind}" data-q="${esc(q)}" ${page===pages?'disabled':''}>下一页</button><span class="page-label">第 ${page} / ${pages} 页</span></nav>`;}
  function collectionsPage(r){const q=r.params.get('q')||'',shown=collections.filter(c=>c.name.includes(q));return `${pageHead('PEOPLE COLLECTIONS','人物合集','把常一起出现的人物放在一起浏览。收藏人物不会确认他们是同一个人。',`<button class="primary" data-action="new-collection">新建合集</button>`)}${tabs('collections')}<div class="layout-row"><label class="searchbox">${iconSearch}<input id="collectionSearch" type="search" placeholder="搜索合集" value="${esc(q)}" aria-label="搜索合集"></label><div class="toolbar"><span class="result-line">${shown.length} 个合集</span></div></div>${shown.length?`<section class="collection-grid">${shown.map(collectionCard).join('')}</section>`:emptyState('没有找到这个合集','试试其他名字，或清空搜索条件。')}`;}
  function collectionCard(c){return `<button class="collection-card" data-collection="${c.id}"><div class="collection-cover">${c.colors.length?c.colors.map((color,i)=>portrait(color,i+c.people.length)).join(''):'<div class="empty-cover">新建合集</div>'}<div class="cover-caption"><span>人物合集</span><span>${c.people.length} 位人物</span></div></div><div class="collection-body"><strong>${c.name}</strong><p>${c.desc}</p><footer><span>${c.count}</span><span>打开合集&nbsp; ›</span></footer></div></button>`;}
  function collectionDetail(id){const c=collections.find(x=>x.id===id)||collections[0];return `${pageHead('COLLECTION','合集详情',c.desc,`<button data-action="collection-back">返回合集</button>`)}<div class="crumbline page-crumb"><a href="#people">人物</a><span>›</span><a href="#collections">合集</a><span>›</span><strong>${c.name}</strong></div><section class="person-detail"><div class="face-stack">${c.people.slice(0,3).map((pid,i)=>{const p=people.find(x=>x.id===pid);return portrait(p.color,i)}).join('')}</div><div><strong>${c.name}</strong><small>${c.count} · 收藏是浏览归类，不代表人物身份确认</small></div></section><div class="small-heading"><h2>合集中的人物</h2><p>${c.people.length} 位</p></div>${c.people.length?`<section class="person-grid">${c.people.map(pid=>personCard(people.find(p=>p.id===pid))).join('')}</section>`:emptyState('这个合集还没有人物','回到人物目录，之后可把熟悉的人物收藏进来。')}${c.people.length?`<div class="small-heading"><h2>最近收录的照片</h2><p>示例照片</p></div><div class="photo-sample-grid">${[0,1,2,3,4,5].map(i=>`<div class="photo-sample">${photoArt(i)}</div>`).join('')}</div>`:emptyState('暂时没有收录照片','加入人物后，这里会显示合集中的照片。')}`;}
  function personDetail(id){const p=people.find(x=>x.id===id)||people[0];return `${pageHead('PERSON ALBUM',p.name,'人物相册 · 示例照片与合集关系',`<button data-action="person-back">返回人物</button>`)}<div class="crumbline page-crumb"><a href="#people">人物</a><span>›</span><strong>${p.name}</strong></div><section class="person-detail">${portrait(p.color,people.indexOf(p))}<div><strong>${p.name}</strong><small>${p.photos} · 已命名人物</small><div class="people-links">${collections.filter(c=>c.people.includes(p.id)).map(c=>`<span class="soft-tag">${c.name}</span>`).join('')}</div></div></section><div class="small-heading"><h2>最近的照片</h2><p>插画示意</p></div><div class="photo-sample-grid">${[0,1,2,3,4,5].map(i=>`<div class="photo-sample">${photoArt(i+people.indexOf(p))}</div>`).join('')}</div>`;}
  function ignoredPage(){return `${organizeHeader('faces')}<div class="ignored-heading"><h2>已忽略的人脸</h2><button class="quiet" data-go="${esc(state.facesRoute||'faces')}">返回未识别人脸</button></div><div class="toolbar face-filter"><button class="pill active" data-ignore-filter="all">全部 · ${ignored.length}</button><button class="pill" data-ignore-filter="TEMPORARY">暂时忽略 · ${ignored.filter(x=>x.state==='TEMPORARY').length}</button><button class="pill" data-ignore-filter="EXCLUDED">明确排除 · ${ignored.filter(x=>x.state==='EXCLUDED').length}</button></div><section class="faces-grid">${ignored.filter(x=>!state.ignoreFilter||state.ignoreFilter==='all'||x.state===state.ignoreFilter).map((x,i)=>`<article class="face-tile">${portrait(x.color,i)}<strong>${x.id.toUpperCase()} · ${x.state==='TEMPORARY'?'暂时忽略':'明确排除'}</strong><small>原照片仍保留</small><div class="face-actions"><button data-restore="${x.id}">恢复这张脸</button></div></article>`).join('')}</section>`;}
  function emptyState(title,desc){return `<div class="empty"><div class="empty-art"><svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5m-12-10h4"/></svg></div><h2>${title}</h2><p>${desc}</p></div>`;}
  function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function render(){const r=route();if(['unnamed','faces','organize'].includes(r.page)){const current=location.hash.slice(1)||'organize';if(r.page==='faces')state.facesRoute=current;else state.unnamedRoute=current;state.organizeRoute=current;}document.querySelectorAll('[data-primary]').forEach(a=>a.classList.toggle('active',a.dataset.primary===(['people','collections','organize','unnamed','faces','ignored','person','collection-detail'].includes(r.page)?'people':r.page)));if(r.page==='people')main.innerHTML=peoplePage(r);else if(r.page==='organize')main.innerHTML=organizePage(r);else if(r.page==='unnamed')main.innerHTML=unnamedPage(r);else if(r.page==='faces')main.innerHTML=facePage(r);else if(r.page==='collections')main.innerHTML=collectionsPage(r);else if(r.page==='collection')main.innerHTML=collectionDetail(r.id);else if(r.page==='person')main.innerHTML=personDetail(r.id);else if(r.page==='ignored')main.innerHTML=ignoredPage();else if(r.page==='photos'||r.page==='places')main.innerHTML=`${pageHead(r.page==='photos'?'PHOTOS':'PLACES',r.page==='photos'?'照片':'地点','此原型聚焦人物整理。',`<button data-action="people-back">回到人物</button>`)}${emptyState('这个页面仅作导航示意','返回人物继续浏览样板。')}`;else main.innerHTML=peoplePage(r);bindPage(r);}
  function openModal(title,description,content,confirmLabel='确认操作',onConfirm=()=>{}){modal.innerHTML=`<div class="modal-inner"><div class="modal-head"><div><h2>${title}</h2><p>${description}</p></div><button class="modal-close" type="button" data-modal-close aria-label="关闭">×</button></div><div class="modal-content">${content}</div><div class="modal-actions"><button data-modal-close>取消</button><button class="primary" id="modalConfirm">${confirmLabel}</button></div></div>`;modal.showModal();modal.querySelector('#modalConfirm').onclick=()=>{const result=onConfirm(modal);if(result!==false)modal.close();};modal.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>modal.close());}
  function nameGroup(id){const g=unnamed.find(x=>x.id===id);openModal('给这组人物保存名字',`这组包含 ${g.faces} 张脸、来自 ${g.photos} 张照片。保存后会显示在人物列表。`,`<label>人物名字<input id="groupName" maxlength="30" placeholder="例如：小姨" autofocus></label><div class="modal-note">这会为现有分组命名。若这些脸属于已经命名的人物，请使用“并入已有”。</div>`,`保存名字`,dlg=>{const name=dlg.querySelector('#groupName').value.trim();if(!name){toast('请先填写人物名字');return false;}state.named[id]=name;state.hidden.add(id);people.unshift({id:`named-${id}`,name,photos:`${g.photos} 张照片`,color:g.color});toast(`已为人物组保存名字「${name}」`);render();});}
  function mergeGroup(id){const options=people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');openModal('并入已有的人物','把这组已聚合的人脸归到已确认的人物名下。',`<label>选择人物<select id="mergeTarget">${options}</select></label><div class="modal-note">这会确认该组人脸与所选人物属于同一人。</div>`,'确认并入',dlg=>{const p=people.find(x=>x.id===dlg.querySelector('#mergeTarget').value);const g=unnamed.find(x=>x.id===id);state.hidden.add(id);toast(`已将 ${g.faces} 张脸并入「${p.name}」`);render();});}
  function confirmFace(id){const f=faceData.find(x=>x.id===id);const opts=people.map(p=>`<option value="${p.id}" ${f?.suggestion===p.name?'selected':''}>${p.name}</option>`).join('');openModal(f?.kind==='suggested'?'确认人物':'指派人物',f?.kind==='suggested'?`系统建议「${f.suggestion}」，请确认这张脸的归属。`:'这张脸暂无可靠建议，请选择熟悉的人物。',`<label>归属人物<select id="faceTarget">${opts}</select></label><div class="modal-note">确认人物会改变这张脸的归属；它与加入合集是不同操作。</div>`,'确认归属',dlg=>{const p=people.find(x=>x.id===dlg.querySelector('#faceTarget').value);state.confirmed.add(id);state.selected.delete(id);toast(`已将 ${id.toUpperCase()} 确认为「${p.name}」`);render();});}
  function bindPage(r){const peopleSearch=document.querySelector('#peopleSearch');if(peopleSearch)peopleSearch.oninput=e=>{const params=new URLSearchParams(r.params);params.set('q',e.target.value);history.replaceState(null,'',`#people?${params}`);render();const el=document.querySelector('#peopleSearch');el.focus();el.setSelectionRange(el.value.length,el.value.length);};const colSearch=document.querySelector('#collectionSearch');if(colSearch)colSearch.oninput=e=>{const params=new URLSearchParams(r.params);params.set('q',e.target.value);history.replaceState(null,'',`#collections?${params}`);render();const el=document.querySelector('#collectionSearch');el.focus();el.setSelectionRange(el.value.length,el.value.length);};const sort=document.querySelector('#sortSelect');if(sort)sort.onchange=e=>{const params=new URLSearchParams(r.params);params.set('sort',e.target.value);history.replaceState(null,'',`#people?${params}`);render();};const uSearch=document.querySelector('#unnamedSearch');if(uSearch)uSearch.oninput=e=>{const params=new URLSearchParams(r.params);params.set('q',e.target.value);params.set('page','1');history.replaceState(null,'',`#unnamed?${params}`);render();const el=document.querySelector('#unnamedSearch');el.focus();el.setSelectionRange(el.value.length,el.value.length);};const fSearch=document.querySelector('#faceSearch');if(fSearch)fSearch.oninput=e=>{const params=new URLSearchParams(r.params);params.set('q',e.target.value);params.set('page','1');history.replaceState(null,'',`#faces?${params}`);render();const el=document.querySelector('#faceSearch');el.focus();el.setSelectionRange(el.value.length,el.value.length);};}
  main.addEventListener('click',e=>{const reset=e.target.closest('#resetBtn');if(reset){state.selected.clear();state.hidden.clear();state.confirmed.clear();state.named={};state.ignoreFilter='all';state.organizeRoute='organize';state.unnamedRoute='unnamed';state.facesRoute='faces';people.splice(0,people.length,...JSON.parse(JSON.stringify(initialData.people)));collections.splice(0,collections.length,...JSON.parse(JSON.stringify(initialData.collections)));ignored.splice(0,ignored.length,...JSON.parse(JSON.stringify(initialData.ignored)));go('people');toast('样板已重置');return;}const person=e.target.closest('[data-person]');if(person){go(`person/${person.dataset.person}?from=${encodeURIComponent(location.hash.slice(1)||'people')}`);return;}const collection=e.target.closest('[data-collection]');if(collection){go(`collection/${collection.dataset.collection}?from=${encodeURIComponent(location.hash.slice(1)||'collections')}`);return;}const gName=e.target.closest('[data-name-group]');if(gName){nameGroup(gName.dataset.nameGroup);return;}const sel=e.target.closest('[data-select-face]');if(sel){const id=sel.dataset.selectFace;if(state.selected.has(id))state.selected.delete(id);else state.selected.add(id);render();return;}const confirm=e.target.closest('[data-confirm-face]');if(confirm){confirmFace(confirm.dataset.confirmFace);return;}const filter=e.target.closest('[data-filter]');if(filter&&!filter.dataset.page){if(['all','suggested','none','low'].includes(filter.dataset.filter)){state.selected.clear();go(`faces?filter=${filter.dataset.filter}&page=1`);return;}}const groupPage=e.target.closest('[data-group-page]');if(groupPage){go(`unnamed?page=${groupPage.dataset.groupPage}&q=${encodeURIComponent(groupPage.dataset.q||'')}&sort=${groupPage.dataset.sort||'recent'}`);return;}const page=e.target.closest('[data-page]');if(page){state.selected.clear();go(`faces?filter=${page.dataset.filter}&page=${page.dataset.page}&q=${encodeURIComponent(page.dataset.q||'')}`);return;}const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='clear-selection'){state.selected.clear();render();}else if(a==='confirm-selected'){const ids=[...state.selected];if(!ids.length)return;openModal('确认所选人脸','为选中的人脸指定同一位人物。',`<p>将确认 ${ids.length} 张脸的归属。请选择人物：</p><label>归属人物<select id="bulkTarget">${people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><div class="modal-note">批量确认会清空当前选择，仍停留在当前筛选条件和页码。</div>`,'确认所选',dlg=>{const p=people.find(x=>x.id===dlg.querySelector('#bulkTarget').value);ids.forEach(id=>state.confirmed.add(id));state.selected.clear();toast(`已确认 ${ids.length} 张脸归入「${p.name}」`);render();});}else if(a==='ignored')go('ignored');else if(a==='updates')openModal('识别更新待确认','有两条识别结果等待你决定。',`<div class="modal-note">候选更新：林妈妈 → 林妈妈（高相似度）<br>候选更新：外公 → 未知人物（需要复核）</div><div class="modal-actions" style="margin-top:14px"><button data-dismiss-update>暂不处理</button><button class="primary" data-dismiss-update>标记已查看</button></div>`,'关闭',()=>{toast('待确认列表已查看');});else if(a==='tools')openModal('识别工具','用于处理尚未归类的照片。',`<div class="modal-note">补匹配未归类人脸<br><br>范围：全部图库（示例）</div><div class="modal-actions" style="margin-top:14px"><button data-tool-run>开始补匹配</button><button data-tool-run>查看上次进度</button></div>`,'知道了',()=>true);else if(a==='history')openModal('操作历史','最近的示例操作记录。',`<div class="modal-note">今天 10:42　确认 2 张人脸归入小雨<br><br>昨天 16:08　创建人物合集「一家人的日常」<br><br>昨天 11:30　暂时忽略 1 张人脸</div>`,'完成',()=>true);else if(a==='new-collection')openModal('新建合集','把常一起出现的人物放在一起浏览。',`<label>合集名称<input id="collectionName" placeholder="例如：旅行伙伴"></label><label>简介（可选）<input id="collectionDesc" placeholder="给这个合集写一句话"></label><div class="modal-note">新建合集只是收藏整理，不会确认人物身份。</div>`,'创建合集',dlg=>{const name=dlg.querySelector('#collectionName').value.trim();if(!name){toast('请先填写合集名称');return false;}collections.unshift({id:`new-${Date.now()}`,name,desc:dlg.querySelector('#collectionDesc').value||'新创建的人物合集',people:[],count:'0 位人物 · 0 张照片',colors:[]});toast(`已创建合集「${name}」`);render();});else if(a==='collection-back')go(route().params.get('from')||'collections');else if(a==='person-back')go(route().params.get('from')||'people');else if(a==='people-back')go('people');else if(a==='organize-back')go('organize');return;}const goButton=e.target.closest('[data-go]');if(goButton){go(goButton.dataset.go);return;}const restore=e.target.closest('[data-restore]');if(restore){const item=ignored.find(x=>x.id===restore.dataset.restore);ignored.splice(ignored.indexOf(item),1);toast('已恢复这张脸');render();return;}const ifilter=e.target.closest('[data-ignore-filter]');if(ifilter){state.ignoreFilter=ifilter.dataset.ignoreFilter;render();return;}const merge=e.target.closest('[data-merge-group]');if(merge){mergeGroup(merge.dataset.mergeGroup);return;}const query=e.target.closest('[data-dismiss-update]');if(query){toast('已更新待确认状态');modal.close();return;}if(e.target.closest('[data-tool-run]')){toast('补匹配已加入示例任务');modal.close();return;}});
  document.body.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')==='#'){e.preventDefault();}});
  document.querySelector('#helpBtn').onclick=()=>openModal('这是一份交互样板','页面中的人物、照片与操作结果都是合成示例。',`<div class="help-content"><strong>人物</strong>展示已命名的人物。<br><strong>合集</strong>用于收藏常一起出现的人物，不代表身份确认。<br><strong>待整理</strong>只分开未命名人物和未识别人脸的入口，原有操作保持不变。<br><br>操作只在当前页面内存中生效，点击“重置样板”可恢复初始示例。</div>`,'明白了',()=>true);
  document.addEventListener('change',e=>{if(e.target.id==='unnamedSort'){const r=route(),params=new URLSearchParams(r.params);params.set('sort',e.target.value);params.set('page','1');go(`unnamed?${params}`);}});
  modal.addEventListener('click',e=>{if(e.target===modal){modal.close();return;}if(e.target.closest('[data-dismiss-update]')){toast('已更新待确认状态');modal.close();return;}if(e.target.closest('[data-tool-run]')){toast('补匹配已加入示例任务');modal.close();return;}});window.addEventListener('hashchange',()=>{state.selected.clear();render();});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.open)modal.close();});
  render();
})();
